[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<meta name="description" content="A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era.">
<style>
/* ===== RESET & BASE ===== */
*,*::before,*::after { box-sizing:border-box; margin:0; padding:0; }

:root {
  --bg: #0A0A0A;
  --bg-elevated: #141414;
  --bg-card: #1A1A1A;
  --text: #FFFFFF;
  --text-secondary: #A0A0A0;
  --text-muted: #666666;
  --accent: #3B82F6;
  --accent-glow: rgba(59,130,246,0.3);
  --border: rgba(255,255,255,0.08);
  --border-light: rgba(255,255,255,0.14);
  --radius: 8px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --max-width: 1280px;
  --nav-height: 72px;
  --transition: 0.3s cubic-bezier(0.4,0,0.2,1);
  --transition-slow: 0.6s cubic-bezier(0.4,0,0.2,1);
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }

a { color: var(--text); text-decoration: none; transition: color var(--transition); }

button {
  cursor: pointer;
  border: none;
  font-family: inherit;
  font-size: inherit;
}

ul, ol { list-style: none; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 40px;
}

/* ===== TYPOGRAPHY ===== */
h1 { font-size: clamp(2.5rem, 5vw, 4.5rem); font-weight: 700; line-height: 1.1; letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 4vw, 3.5rem); font-weight: 700; line-height: 1.15; letter-spacing: -0.015em; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); font-weight: 600; line-height: 1.3; }
h4 { font-size: 1.125rem; font-weight: 600; line-height: 1.4; }

.section-label {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-secondary);
  margin-bottom: 12px;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 640px;
  margin-top: 16px;
  line-height: 1.6;
}

.text-gradient {
  background: linear-gradient(135deg, #3B82F6 0%, #60A5FA 50%, #93C5FD 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.95rem;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover {
  background: #2563EB;
  box-shadow: 0 4px 24px var(--accent-glow);
  transform: translateY(-1px);
}

.btn-outline {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border-light);
}
.btn-outline:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(59,130,246,0.05);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  padding: 8px 16px;
  font-size: 0.85rem;
}
.btn-ghost:hover {
  color: var(--text);
}

/* ===== NAVIGATION ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--nav-height);
  background: rgba(10,10,10,0.85);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border-bottom: 1px solid var(--border);
  transition: background var(--transition);
}

.nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.nav-logo {
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-links a {
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition);
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
  background: rgba(255,255,255,0.05);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.lang-selector {
  position: relative;
}

.lang-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  background: rgba(255,255,255,0.05);
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-weight: 500;
  transition: all var(--transition);
}
.lang-btn:hover {
  border-color: var(--border-light);
  color: var(--text);
}
.lang-btn .globe-icon { font-size: 1rem; }
.lang-btn .chevron-down { font-size: 0.65rem; transition: transform var(--transition); }

.lang-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  min-width: 180px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 6px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition);
  box-shadow: 0 12px 40px rgba(0,0,0,0.5);
}
.lang-dropdown.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.lang-dropdown button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 10px 14px;
  background: transparent;
  color: var(--text-secondary);
  border-radius: 4px;
  font-size: 0.9rem;
  transition: all var(--transition);
}
.lang-dropdown button:hover,
.lang-dropdown button.selected {
  color: var(--text);
  background: rgba(255,255,255,0.06);
}
.lang-dropdown button.selected::after {
  content: " ✓";
  color: var(--accent);
  font-size: 0.75rem;
}

.menu-toggle {
  display: none;
  width: 40px;
  height: 40px;
  background: transparent;
  border: none;
  flex-direction: column;
  justify-content: center;
  gap: 6px;
  padding: 8px;
}
.menu-toggle span {
  display: block;
  height: 2px;
  background: var(--text);
  border-radius: 2px;
  transition: all var(--transition);
}
.menu-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px,5px); }
.menu-toggle.active span:nth-child(2) { opacity: 0; }
.menu-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(6px,-6px); }

@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(10,10,10,0.98);
    backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--border);
    padding: 16px;
    gap: 4px;
  }
  .nav-links.open a {
    padding: 12px 16px;
    font-size: 1rem;
    width: 100%;
  }
  .menu-toggle { display: flex; }
}

/* ===== HERO ===== */
.hero {
  padding-top: var(--nav-height);
  min-height: 100vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 70%;
  height: 200%;
  background: radial-gradient(ellipse at center, rgba(59,130,246,0.06) 0%, transparent 70%);
  pointer-events: none;
}

.hero .container {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding-top: 60px;
  padding-bottom: 60px;
}

.hero-carousel {
  position: relative;
  width: 100%;
  max-width: 800px;
  min-height: 420px;
}

.hero-slide {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  opacity: 0;
  transform: translateX(40px);
  transition: all var(--transition-slow);
  pointer-events: none;
}
.hero-slide.active {
  opacity: 1;
  transform: translateX(0);
  pointer-events: all;
}
.hero-slide.exit {
  opacity: 0;
  transform: translateX(-40px);
}

.hero-badge {
  display: inline-block;
  padding: 6px 16px;
  background: rgba(59,130,246,0.1);
  border: 1px solid rgba(59,130,246,0.2);
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.hero-title {
  font-size: clamp(2.2rem, 4.5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.12;
  letter-spacing: -0.025em;
}

.hero-desc {
  font-size: 1.15rem;
  color: var(--text-secondary);
  max-width: 560px;
  line-height: 1.6;
}

.hero-dots {
  display: flex;
  gap: 10px;
  margin-top: 32px;
}

.hero-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-light);
  transition: all var(--transition);
  border: none;
  padding: 0;
}
.hero-dot.active {
  background: var(--accent);
  box-shadow: 0 0 12px var(--accent-glow);
  width: 32px;
  border-radius: 5px;
}

/* ===== SECTION COMMON ===== */
.section {
  padding: 120px 0;
  position: relative;
}

.section-header {
  margin-bottom: 60px;
}

.section-header.centered {
  text-align: center;
}
.section-header.centered .section-subtitle {
  margin-left: auto;
  margin-right: auto;
}

/* ===== TEAM CAROUSEL ===== */
.team-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

.team-tab {
  padding: 10px 24px;
  border-radius: 100px;
  background: transparent;
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 0.95rem;
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.team-tab:hover {
  color: var(--text);
  border-color: var(--border-light);
}
.team-tab.active {
  background: rgba(59,130,246,0.12);
  border-color: var(--accent);
  color: var(--accent);
}

.team-carousel-wrapper {
  position: relative;
}

.team-cards {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  padding-bottom: 8px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.team-cards::-webkit-scrollbar { display: none; }

.team-card {
  flex: 0 0 380px;
  scroll-snap-align: start;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  transition: all var(--transition);
}
.team-card:hover {
  border-color: var(--border-light);
  transform: translateY(-2px);
}

.team-card-avatar {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: linear-gradient(135deg, #1e3a5f, #2d1b4e);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--accent);
  flex-shrink: 0;
}

.team-card-info h4 {
  font-size: 1.15rem;
  color: var(--text);
  margin-bottom: 2px;
}

.team-card-info p {
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.team-card-office {
  font-size: 0.85rem;
  color: var(--accent);
  font-weight: 500;
}

.team-card-quote {
  font-size: 0.95rem;
  color: var(--text-secondary);
  line-height: 1.6;
  font-style: italic;
  flex: 1;
}

.team-card-quote::before {
  content: '"';
}

.team-card-quote::after {
  content: '"';
}

.team-carousel-arrows {
  display: flex;
  gap: 8px;
  margin-top: 24px;
  justify-content: flex-end;
}

.team-carousel-arrows button {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--bg-card);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  transition: all var(--transition);
}
.team-carousel-arrows button:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(59,130,246,0.08);
}

@media (max-width: 768px) {
  .team-card { flex: 0 0 300px; }
}

/* ===== WORK SHOWCASE ===== */
.work-scroll {
  position: relative;
}

.work-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  padding-bottom: 8px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.work-track::-webkit-scrollbar { display: none; }

.work-card {
  flex: 0 0 420px;
  scroll-snap-align: start;
  border-radius: var(--radius-lg);
  background: var(--bg-card);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
}
.work-card:hover {
  border-color: var(--border-light);
  transform: translateY(-2px);
}

.work-card-thumb {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #1a1a2e, #16213e, #0f3460);
  position: relative;
  overflow: hidden;
}
.work-card-thumb::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(10,10,10,0.4), transparent);
}

.work-card-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.work-card-client {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
}

.work-card-title {
  font-size: 1.2rem;
  font-weight: 700;
  line-height: 1.3;
}

.work-card-quote {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.55;
  font-style: italic;
}

.work-card-attribution {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-style: normal;
}

.work-arrows {
  display: flex;
  gap: 8px;
  margin-top: 24px;
  justify-content: flex-end;
}

.work-arrows button {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--bg-card);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  transition: all var(--transition);
}
.work-arrows button:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(59,130,246,0.08);
}

@media (max-width: 600px) {
  .work-card { flex: 0 0 300px; }
}

/* ===== CTA BANNER ===== */
.cta-banner {
  padding: 100px 0;
  text-align: center;
  position: relative;
}

.cta-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(59,130,246,0.08) 0%, transparent 60%);
  pointer-events: none;
}

.cta-banner h2 {
  margin-bottom: 20px;
  font-size: clamp(2.2rem, 4.5vw, 3.5rem);
}

.cta-banner p {
  color: var(--text-secondary);
  font-size: 1.15rem;
  max-width: 680px;
  margin: 0 auto 32px;
  line-height: 1.6;
}

/* ===== HOW WE WORK ===== */
.how-we-work {
  background: var(--bg-elevated);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.how-we-work .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.how-we-work h2 {
  font-size: clamp(2rem, 3.5vw, 3rem);
  margin-bottom: 20px;
}

.how-we-work p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.65;
  margin-bottom: 28px;
}

.how-we-work-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #0f2027, #203a43, #2c5364);
  border-radius: var(--radius-xl);
  position: relative;
  overflow: hidden;
}
.how-we-work-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 40%, rgba(59,130,246,0.15) 0%, transparent 70%);
}

@media (max-width: 768px) {
  .how-we-work .container {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .how-we-work-visual {
    aspect-ratio: 16/9;
  }
}

/* ===== INSIGHTS ===== */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 24px;
}

.insight-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: all var(--transition);
}
.insight-card:hover {
  border-color: var(--border-light);
  transform: translateY(-2px);
}

.insight-type {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
}

.insight-type-icon {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
}

.insight-title {
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1.35;
}

.insight-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--accent);
  margin-top: auto;
}
.insight-link:hover {
  gap: 10px;
  text-decoration: underline;
}

/* ===== PRINCIPLES ===== */
.principles-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.principle-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 40px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: all var(--transition);
}
.principle-card:hover {
  border-color: var(--border-light);
}

.principle-number {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.08em;
}

.principle-title {
  font-size: 1.35rem;
  font-weight: 700;
  line-height: 1.3;
}

.principle-desc {
  color: var(--text-secondary);
  font-size: 1rem;
  line-height: 1.6;
}

@media (max-width: 768px) {
  .principles-grid {
    grid-template-columns: 1fr;
  }
}

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-elevated);
  border-top: 1px solid var(--border);
  padding: 80px 0 40px;
}

.footer-ctas {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  padding-bottom: 60px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 60px;
}

.footer-cta-box h3 {
  margin-bottom: 12px;
  font-size: 1.25rem;
}

.footer-cta-box p {
  color: var(--text-secondary);
  margin-bottom: 20px;
  font-size: 0.95rem;
  line-height: 1.5;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 20px;
}

.footer-links {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}

.footer-links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
}
.footer-links a:hover {
  color: var(--text);
}

.footer-legal {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.footer-legal a {
  color: var(--text-muted);
  font-size: 0.8rem;
}
.footer-legal a:hover {
  color: var(--text-secondary);
}

@media (max-width: 768px) {
  .footer-ctas {
    grid-template-columns: 1fr;
  }
  .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 50%;
