    dropdown.classList.toggle('open');
    langBtn.setAttribute('aria-expanded', !isOpen);
    langBtn.querySelector('.chevron-down').style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
  });

  options.forEach(opt => {
    opt.addEventListener('click', (e) => {
      e.stopPropagation();
      options.forEach(o => { o.classList.remove('selected'); o.setAttribute('aria-selected', 'false'); });
      opt.classList.add('selected');
      opt.setAttribute('aria-selected', 'true');
      langLabel.textContent = opt.dataset.lang === 'global-en' ? 'Global EN' :
                                opt.dataset.lang === 'france-fr' ? 'France FR' : 'China CN';
      dropdown.classList.remove('open');
      langBtn.setAttribute('aria-expanded', 'false');
      langBtn.querySelector('.chevron-down').style.transform = 'rotate(0deg)';
    });
  });

  document.addEventListener('click', () => {
    dropdown.classList.remove('open');
    langBtn.setAttribute('aria-expanded', 'false');
    langBtn.querySelector('.chevron-down').style.transform = 'rotate(0deg)';
  });
})();

/* ===== MOBILE MENU ===== */
(function() {
  const menuToggle = document.getElementById('menuToggle');
  const navLinks = document.getElementById('navLinks');

  menuToggle.addEventListener('click', () => {
    const isOpen = navLinks.classList.contains('open');
    navLinks.classList.toggle('open');
    menuToggle.classList.toggle('active');
    menuToggle.setAttribute('aria-expanded', !isOpen);
  });

  // Close menu on link click
  navLinks.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', () => {
      navLinks.classList.remove('open');
      menuToggle.classList.remove('active');
      menuToggle.setAttribute('aria-expanded', 'false');
    });
  });
})();

